Auth::requireLogin();
$actor=Auth::user();
$type=(string)($_GET['type']??$_POST['report_type']??'');
if(!isset(ManagementReportsRepository::TYPES[$type])||!ManagementReportsRepository::canPrepare($type)){http_response_code(403);exit('شما به آماده‌سازی این نوع گزارش دسترسی ندارید.');}
$currentTemplate=ManagementReportsRepository::template($type);if(!$currentTemplate){http_response_code(503);exit('قالب فعال این گزارش هنوز راه‌اندازی نشده است.');}
$id=(int)($_GET['id']??$_POST['submission_id']??0);$submission=$id?ManagementReportsRepository::submission($id):null;if($id&&!$submission){http_response_code(404);exit('گزارش در دسترس نیست.');}
if($submission&&((int)$submission['submitter_id']!==(int)Auth::user()['id']||$submission['report_type']!==$type)){http_response_code(403);exit('دسترسی غیرمجاز است.');}
$template=$submission?(ManagementReportsRepository::templateForSubmission($submission)?:$currentTemplate):$currentTemplate;
$editable=!$submission||in_array($submission['status'],['draft','returned'],true);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/management-report-prepare.php?type='.$type.($id?'&id='.$id:''));}
