        $periods=ManagementReportsRepository::periods();$periodMap=[];foreach($periods as $period)$periodMap[$period['period_key']]=$period;$periodKey=(string)($_POST['period_key']??'');if(!isset($periodMap[$periodKey])&&$submission&&$submission['period_key']===$periodKey)$periodMap[$periodKey]=['period_key'=>$submission['period_key'],'period_title'=>$submission['period_title'],'period_start'=>$submission['period_start'],'period_end'=>$submission['period_end']];if(!isset($periodMap[$periodKey]))throw new InvalidArgumentException('دوره گزارش معتبر نیست.');
        $target=($_POST['action']??'draft')==='submit'?'submitted':'draft';
        if($target==='submitted')foreach($template['sections'] as $section)foreach($section['fields'] as $field)if(in_array($field['field_type'],['file','attachment'],true)&&(int)$field['is_required']){$hasExisting=$submission&&array_filter($submission['attachments'],static fn($a)=>(int)$a['field_id']===(int)$field['id']);$file=$_FILES['files']['error'][$field['id']]??UPLOAD_ERR_NO_FILE;if(!$hasExisting&&$file!==UPLOAD_ERR_OK)throw new InvalidArgumentException('بارگذاری فایل «'.$field['label'].'» الزامی است.');}
        $id=ManagementReportsRepository::saveSubmission($type,$id,$periodMap[$periodKey],$_POST['values']??[],'draft');
        foreach($template['sections'] as $section)foreach($section['fields'] as $field)if(in_array($field['field_type'],['file','attachment'],true)){
            $fieldId=(int)$field['id'];$error=$_FILES['files']['error'][$fieldId]??UPLOAD_ERR_NO_FILE;if($error===UPLOAD_ERR_NO_FILE)continue;
            $file=['name'=>$_FILES['files']['name'][$fieldId]??'','type'=>$_FILES['files']['type'][$fieldId]??'','tmp_name'=>$_FILES['files']['tmp_name'][$fieldId]??'','error'=>$error,'size'=>$_FILES['files']['size'][$fieldId]??0];
            $upload=Upload::save($file,'uploads/management-reports',['pdf','doc','docx','xls','xlsx','csv','jpg','jpeg','png','webp','txt'],15*1024*1024);if(!$upload['ok'])throw new InvalidArgumentException($field['label'].': '.$upload['error']);ManagementReportsRepository::addAttachment($id,$fieldId,$upload);
        }
        if($target==='submitted')$id=ManagementReportsRepository::saveSubmission($type,$id,$periodMap[$periodKey],$_POST['values']??[],'submitted');
        Auth::log((int)Auth::user()['id'],$target==='submitted'?'management_report_submitted':'management_report_draft_saved','management_report_submissions',$id);
        flash($target==='submitted'?'گزارش با موفقیت ثبت نهایی شد.':'پیش‌نویس گزارش ذخیره شد.');redirect($target==='submitted'?'/admin/management-report-view.php?id='.$id:'/admin/management-report-prepare.php?type='.$type.'&id='.$id);
    }catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Management report prepare: '.$e->getMessage());flash('ذخیره گزارش انجام نشد. لطفاً دوباره تلاش کنید.','danger');}
    redirect('/admin/management-report-prepare.php?type='.$type.($id?'&id='.$id:''));
}
$periods=ManagementReportsRepository::periods();if($submission&&!array_filter($periods,static fn($period)=>$period['period_key']===$submission['period_key']))array_unshift($periods,['period_key'=>$submission['period_key'],'period_title'=>$submission['period_title'],'period_start'=>$submission['period_start'],'period_end'=>$submission['period_end']]);$valueMap=[];$attachmentMap=[];if($submission){foreach($submission['values'] as $value)$valueMap[(int)$value['field_id']]=$value;foreach($submission['attachments'] as $attachment)$attachmentMap[(int)$attachment['field_id']][]=$attachment;}
$userOptions=[];$actionOptions=[];$taskOptions=[];$actionTypes=[];
try{
    $userOptions=ActionHubService::assignableUsers($actor);
    $actionOptions=ActionHubService::actions($actor,[],200);
    $actionTypes=ActionHubService::types();
