    if($accessibleIds&&Database::tableExists('work_planner_tasks'))$taskOptions=Database::fetchAll('SELECT t.id,t.title,t.status,t.due_date,u.name user_name FROM work_planner_tasks t LEFT JOIN users u ON u.id=t.user_id WHERE t.user_id IN ('.implode(',',array_fill(0,count($accessibleIds),'?')).') ORDER BY t.updated_at DESC,t.id DESC LIMIT 200',$accessibleIds);
}catch(Throwable $e){error_log('Management report related selectors: '.$e->getMessage());}
